#[test]
fn array_slice_copy_and_callee_store_share_1140() { let p = "struct arr_box { data [4]int }\nfn worker(rows [][]int, done chan<- bool) {\nrows[0][0] = 1\ndone <- true\n}\nfn worker_ints(s []int, done chan<- bool) {\ns[0] = 1\ndone <- true\n}\nfn store_slice(dst [][]int, s []int) {\ndst[0] = s\n}\nfn peek_slice(dst [][]int, s []int) {\n_ = len(dst) + len(s)\n}\nfn clone4(a [4]int) [4]int {\nreturn a\n}\n"; for b in ["done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\ncopy(dst, [][]int{arr[:]})\ntask worker(move dst, done)\narr[0] = 2\n<-done", "done := make(chan bool, 1)\nb := arr_box{data: [4]int{1, 2, 3, 4}}\ndst := [][]int{[]int{0}}\ncopy(dst, [][]int{b.data[:]})\ntask worker(move dst, done)\nb.data[0] = 2\n<-done", "done := make(chan bool, 1)\nvar arr [4]int\ndst := make([][]int, 1)\ncopy(dst, [][]int{arr[1:3]})\ntask worker(move dst, done)\narr[1] = 2\n<-done", "done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\nstore_slice(dst, arr[:])\ntask worker(move dst, done)\narr[0] = 2\n<-done", "done := make(chan bool, 1)\nb := arr_box{data: [4]int{1, 2, 3, 4}}\ndst := [][]int{[]int{0}}\nstore_slice(dst, b.data[:])\ntask worker(move dst, done)\nb.data[0] = 2\n<-done", "done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\nput := fn(d [][]int, s []int) {\nd[0] = s\n}\nput(dst, arr[:])\ntask worker(move dst, done)\narr[0] = 2\n<-done"] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", &format!("{p}fn main() {{\n{b}\n}}\n")).unwrap()); assert_eq!(r.verdict, hy_check::Verdict::Reject, "{b}"); assert!(r.diagnostics.iter().any(|d| d.code == "HYB-E3003"), "{b}: {:?}", r.diagnostics); } for b in ["done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\ncopy(dst, [][]int{clone4(arr)[:]})\ntask worker(move dst, done)\narr[0] = 2\n<-done", "done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\nints := make([]int, 4)\ncopy(ints, arr[:])\ntask worker_ints(move ints, done)\narr[0] = 2\n<-done", "done := make(chan bool, 1)\narr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\npeek_slice(dst, arr[:])\ntask worker(move dst, done)\narr[0] = 2\n<-done", "arr := [4]int{1, 2, 3, 4}\ndst := [][]int{[]int{0}}\ncopy(dst, [][]int{arr[:]})\nstore_slice(dst, arr[:])\narr[0] = 2\ndst[0][0] = 3"] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", &format!("{p}fn main() {{\n{b}\n}}\n")).unwrap()); assert_eq!(r.verdict, hy_check::Verdict::Accept, "{b}: {:?}", r.diagnostics); } }
